    ["GetTrainerServiceDescription(1)"] = "1: string Gives 55 additional armor to party members within 30 yards.  Players may only have one Aura on them per Paladin at any one time.",
    ["GetTrainerServiceDescription(10)"] = "1: string Purifies the friendly target, removing 1 disease effect and 1 poison effect.",
    ["GetTrainerServiceDescription(100)"] = "1: string Brings a dead player back to life with 400 health and 600 mana.  Cannot be cast when in combat.",
    ["GetTrainerServiceDescription(101)"] = "1: string Fills the Paladin with divine wisdom for 30 sec, giving each melee attack a chance to restore 71 of the Paladin's mana.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for 40 sec, granting attacks and spells used against the judged enemy a chance to restore 46 mana to the attacker.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.",
    ["GetTrainerServiceDescription(102)"] = "1: string Places a Blessing on the friendly target, increasing the effects of Holy Light spells used on the target by up to 300 and the effect Flash of Light spells used on the target by up to 85.  Lasts 1 |4hour:hrs;.  Players may only have one Blessing on them per Paladin at any one time.",
    ["GetTrainerServiceDescription(103)"] = "1: string Consecrates the land beneath the Paladin, doing 64 Holy damage over 8 sec to enemies who enter the area. The first 4 enemies who enter the area will take an additional 160 damage over 8 sec.",
    ["GetTrainerServiceDescription(104)"] = "1: string Gives 620 additional armor to party members within 30 yards.  Players may only have one Aura on them per Paladin at any one time.",
    ["GetTrainerServiceDescription(105)"] = "1: string Protects the paladin from all damage and spells for 12 sec, but reduces all damage you deal by 50%.  Applies Forbearance for 1 min. Cannot be cast while Forbearance is active.",
    ["GetTrainerServiceDescription(106)"] = "1: string Heals a friendly target for 210 to 236.",
    ["GetTrainerServiceDescription(107)"] = "1: string Increases chance to block by 30% for 10 sec, and deals 153 Holy damage for each attack blocked while active. Damage caused by Holy Shield causes 20% additional threat.",
    ["GetTrainerServiceDescription(108)"] = "1: string Sends bolts of holy power in all directions, causing 362 to 428 Holy damage to all Undead and Demon targets within 20 yds and stunning them for 2 sec.",
    ["GetTrainerServiceDescription(109)"] = "1: string Heals a friendly target for an amount equal to the Paladin's maximum health and restores 550 of their mana.  Drains all of the Paladin's remaining Mana when used, but does not interrupt Mana regeneration.",
    ["GetTrainerServiceDescription(11)"] = "1: string A targeted party member is protected from all physical attacks for 6 sec, but during that time they cannot attack or use physical abilities.  Players may only have one Blessing on them per Paladin at any one time.  Applies Forbearance for 1 min. Cannot be cast while Forbearance is active.",
    ["GetTrainerServiceDescription(110)"] = "1: string Applies Light's Vigil to the target for 30 sec. Your next Holy Shock cast on them triggers no cooldown and causes enemy targets to suffer 268 to 288 Holy damage and refund 75% of Light's Vigil's Mana cost, or allied targets to heal their party for 473 to 501. You may only have one Light's Vigil active per party.",
    ["GetTrainerServiceDescription(111)"] = "1: string Gives the Paladin a chance to deal additional Holy damage equal to 70% of normal weapon damage.  Only one Seal can be active on the Paladin at any one time.  Lasts 30 sec.\r\n\r\nUnleashing this Seal's energy will judge an enemy, instantly causing 130 to 144 Holy damage, 261 to 287 if the target is stunned or incapacitated.",
    ["GetTrainerServiceDescription(112)"] = "1: string Fills the Paladin with divine fury for 30 sec, causing melee attacks to deal an additional 32 Holy damage. While a shield is equipped, each attack also grants an absorb shield equal to 50% of the Holy damage dealt.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy inflicts 118 to 128 Holy damage to an enemy and taunts the target to attack you for 4 sec.",
    ["GetTrainerServiceDescription(113)"] = "1: string Fills the Paladin with divine light for 30 sec, giving each melee attack a chance to heal the Paladin for 76.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for 40 sec, granting melee attacks made against the judged enemy a chance of healing the attacker for 49.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.",
    ["GetTrainerServiceDescription(114)"] = "1: string Fills the Paladin with holy spirit for 30 sec, granting each melee attack an additional 16 to 56 Holy damage.  Slower weapons cause more Holy damage per swing.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will cause 131 to 143 Holy damage to an enemy.",
    ["GetTrainerServiceDescription(115)"] = "1: string Places a Blessing on the friendly target, increasing melee attack power by 112 for 1 |4hour:hrs;.  Players may only have one Blessing on them per Paladin at any one time.",
