    ["GetTrainerServiceDescription(90)"] = "1: string Places a Blessing on the friendly target, restoring 30 mana every 5 seconds for 1 |4hour:hrs;.  Players may only have one Blessing on them per Paladin at any one time.",
    ["GetTrainerServiceDescription(91)"] = "1: string Causes 274 to 308 Holy damage to an Undead or Demon target.",
    ["GetTrainerServiceDescription(92)"] = "1: string Gives 45 additional Frost resistance to all party and raid members within 30 yards. Players may only have one Aura on them per Paladin at any one time.",
    ["GetTrainerServiceDescription(93)"] = "1: string Hurls a hammer that strikes an enemy for 274 to 302 Holy damage.  Only usable on enemies that have 20% or less health.",
    ["GetTrainerServiceDescription(94)"] = "1: string An instant strike that causes 43% weapon damage plus an additional 19 to 26 as Holy damage.",
    ["GetTrainerServiceDescription(95)"] = "1: string Places a Blessing on the party member, transfering 45 damage taken per hit to the caster.  Lasts 30 sec.  Players may only have one Blessing on them per Paladin at any one time.",
    ["GetTrainerServiceDescription(96)"] = "1: string Heals a friendly target for 850 to 948.",
    ["GetTrainerServiceDescription(97)"] = "1: string Causes 16 Holy damage to any creature that strikes a party member within 30 yards. Players may only have one Aura on them per Paladin at any one time.",
    ["GetTrainerServiceDescription(98)"] = "1: string Gives 45 additional Fire resistance to all party and raid members within 30 yards. Players may only have one Aura on them per Paladin at any one time.",
    ["GetTrainerServiceDescription(99)"] = "1: string Blasts the target with Holy energy, causing 248 to 268 Holy damage to an enemy, or 221 to 239 healing to an ally.",
